We start by proving the following auxiliary statement:

\begin{corollary}\label{cor:amplification_closeness}
    Let $\varsigma_i\ket{w_i}\!\!\bra{v_i}$, $\wt{\varsigma}_i$, $\mu$ and $\nu$ be as defined in Theorem~\ref{thm:uniform_singular_value_transform}.  For any pure state $\ket{\psi}$, let
    \begin{align*}
        \ket{\wt{\phi}} = \left(\sum_{i: \varsigma_i \leq \frac{1 - \mu}{\gamma}}\Tilde{\varsigma_i} \ket{w_i}\!\!\bra{v_i}\right) \ket{\psi},\\
        \ket{\phi} = \left(\sum_{i: \varsigma_i \leq \frac{1 - \mu}{\gamma}} \gamma \varsigma_i \ket{w_i}\!\!\bra{v_i}\right) \ket{\psi}.
    \end{align*}
    Then $\ket{\tilde\phi} = \ket\phi + \ket\nu$ where $\norm{\ket\nu}_2 \le \nu$.
\end{corollary}
\begin{proof}
    We simply verify by calculating
    \begin{align*}
        \norm{\ket\nu}_2 &= \norm{\ket{\tilde\phi} - \ket\phi}_2 \\
          &= \norm{\sum_{i: \varsigma_i \leq \frac{1 - \mu}{\gamma}}(\Tilde{\varsigma_i} - \gamma\varsigma_i) \ket{w_i}\braket{v_i|\psi}}_2 \\
          &= \sqrt{\sum_{i: \varsigma_i \leq \frac{1 - \mu}{\gamma}} \abs{(\Tilde{\varsigma_i} - \gamma\varsigma_i) \braket{v_i|\psi}}^2} \\
          &\le \max_{i: \varsigma_i \leq \frac{1 - \mu}{\gamma}} \abs{\Tilde{\varsigma_i} - \gamma\varsigma_i} \\
          &\le \max_{i: \varsigma_i \leq \frac{1 - \mu}{\gamma}} \gamma\varsigma_i\nu \\
          &\le \nu\,,
    \end{align*}
    where the second inequality is by the guarantee of the algorithm.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
At a high level, the goal of the single-fold adversary will be to use \Cref{thm:uniform_singular_value_transform} to coherently do post selection such that the first $(i - 1)$ repetitions are accepted, in which case the $i$'th repetition should also be accepted with decent probability by the theorem assumption. 

Let $A$ be the unitary that the adversary performs on registers $\reg{AR}^{(\leq k)}$ in the $k$-fold game.  Apply \Cref{thm:uniform_singular_value_transform} with the following projectors and parameters.
\begin{align}
    \Pi &= \left(C^{(< i)} \otimes \id\right) \left(\id \otimes \proj{0}_{\reg{W_0}^{(<i)}}\right) \left(\left(C^{(<i)}\right)^{\dagger} \otimes \id\right)\,, \nonumber\\
    \label{def:tildePi}
    \wt{\Pi} &= (A^{\dagger}_{\reg{A_1R}^{(\leq k)}} \otimes \id)\left(D^{(<i)} \otimes \id\right) \left(A_{\reg{A_1R}^{(\leq k)}}  \otimes \id\right)\,,\\
    \label{def:gamma}
    \gamma &= \frac{1 - \mu}{\sqrt{\delta^{i - 1}}}\,,\\
    \nu &= \mu\sqrt{\tau\delta}\nonumber\,.
\end{align}
Let $W$ be the unitary satisfying the conclusions \Cref{thm:uniform_singular_value_transform} for that choice of parameters.
Note that $W$ acts on $\reg{A}$, the $k$-fold adversaries private register, $\reg{W}_1^{(< i)}$, the $(i - 1)$ many simulated challengers' private workspaces after sending the challenges, $\reg{R}^{(\leq k)}$, the response registers for all $k$ challengers (which $A$ expects to act on), and an ancilla register $\reg{P}$, which will be projected onto the $\proj{+}$ state.  Now consider the following prover for the $1$-fold game (the challenger's actions are included in monospace font to aid understanding).

\begin{longfbox}[breakable=false, padding=1em, margin-top=1em, margin-bottom=1em]
\begin{algorithm}
	\label{prot:non-uniform-adv}
    \textbf{Non-uniform adversary $\Amplify$ for the $1$-fold protocol}
\end{algorithm}
\noindent \textbf{Input: } Quantum registers $\reg{AM}_0^{(\leq k)}\reg{W}_0^{>i}$, index $i$, and slackness parameter $\mu$, and black-box oracle access to $A,C,D$.
\begin{enumerate}
		\item \label[step]{step:initw} Initialize registers $\reg{W}_0^{(< i)}$ to $\ket{0}$, the private workspace registers for the first $(i - 1)$ simulated challengers.
	    \item Send $\reg M_0^i$ to the challenger as the first message.
    \\ \texttt{(Challenger performs $C_{\reg{W}_0^i \reg{M}_0^i}$ and sends $\reg{R^i}$ back.)}
	    \item \label[step]{step:fakechallenge} Perform $C^{(\neq i)}$ on registers $\reg W_0\reg M_0^{(\neq i)}$ to get a state on $\reg W_1 \reg R^{(\neq i)}$.
		\item \label[step]{step:initauxp} Create ancilla register $\reg{P}$ initialized in $\ket{+}_{\reg{P}}$.
    \item \label[step]{step:gslw} Perform $W_{\reg{A}\reg W_1^{(<i)}\reg{R}^{(\leq k)}\reg{P}}$ as defined above.
    \item \label[step]{step:invokeadv} Perform $A_{\reg{AR}^{(\leq k)}}$.
    \item \label[step]{step:fakeverify} Measure $D^{(< i)} \otimes \proj{+}_{\reg{P}}$. If the measurement rejects, abort.  
    \item Send $\reg M_1^i$ to the challenger.
    \\ \texttt{(Challenger measures $D_{\reg{W_1^i}\reg{M_1^i}}$ and accepts or rejects.)}
\end{enumerate}
\end{longfbox}
We analyze the algorithm by describing the state of the combined prover-verifier system after every step.  

\noindent \textbf{After \cref{step:initw}:}
We assume that the registers $\reg{AM_0}^{(\leq k)}$ are initialized in the state $\ket{\aux}_{\reg{AM_0}^{(\leq k)}\reg W_0^{>i}}$ satisfying the theorem statement.  Thus, state of the adversary and challenger after \cref{step:initw} is
\begin{equation*}
    \ket{\init} := \ket{\aux}_{\reg{AM_0}^{(\leq k)}\reg W_0^{(>i)}} \otimes \ket{0}_{\reg W_0^{(\leq i)}}.
\end{equation*}

\noindent \textbf{After \cref{step:initauxp}:}
In \cref{step:fakechallenge}, together with the verifiers action, the verifier and prover perform $C^{(\leq k)}$ on registers $\reg W_0^{(\leq k)}\reg M_0^{(\leq k)}$, so the state of the system after \cref{step:initauxp} is given by
\begin{equation*}
    C^{(\leq k)}\ket{\init} \otimes \ket{+}_{\reg{P}}.
\end{equation*}
This state is in the $+1$ eigenstate of $(\Pi \otimes \proj{+}_{\reg{P}})$ as the first $(i - 1)$ repetitions are initialized correctly, so we can write the state as
\begin{equation*}
    (\Pi \otimes \ket{+}_{\reg{P}})C^{(\leq k)}\ket{\init}.
\end{equation*}

\noindent \textbf{After \cref{step:fakeverify}:}
After measuring $D^{(< i)} \otimes \proj{+}_{\reg P}$, we get the following state. 
\begin{equation*}
    (D^{(<i)} \otimes \bra{+}_{\reg{P}}) AW(\Pi \otimes \ket{+}_{\reg{P}})C^{(\leq k)}\ket{\init}.
\end{equation*}
The state might be subnormalized since we might abort in the event that the measurement rejects; aborting also ensures that the rejection part of the amplitude would not interfere with the rest of the algorithm and the analysis.
Now recall that $\wt{\Pi} = A^{\dagger} D^{(<i)} A$, thus $D^{(<i)} = A \wt{\Pi}A^\dagger$.  Performing this substitution gives us the following expression for the state above. 
\begin{equation*}
    A 
    (\wt{\Pi} \otimes \bra{+}_{\reg{P}})W(\Pi \otimes \ket{+}_{\reg{P}})C^{(\leq k)}\ket{\init}.
\end{equation*}
Note that we choose the parameter at \eqref{def:gamma} so that $\frac{1 - \mu}\gamma = \sqrt{\delta^{i - 1}}$ and thus we can now apply the guarantee of \Cref{cor:amplification_closeness} and get that the state can be written as
\begin{equation*}
    \gamma A\wt{\Pi} \Pi
    C^{(\leq k)}\ket{\init} + \ket\nu
\end{equation*}
for some $\norm{\ket\nu}_2 \le \nu$.
We now use again the fact that $C^{(\leq k)}\ket{\init}$ is invariant under $\Pi$ to remove $\Pi$.
We further plug in the definition of $\wt\Pi$, yielding
\begin{equation*}
    \gamma
    D^{(<i)}AC^{(\leq k)}\ket{\init} + \ket\nu,
\end{equation*}
which is exactly the ``post-selection'' state we would like to prepare up to a small error.

\noindent \textbf{After the final verifier decision:}
After the verifier measures $D_{\reg{W_1^i}\reg{M_1^i}}$, we obtain the state
\begin{equation*}
    \gamma
    D^{(\le i)}AC^{(\leq k)}\ket{\init} + \ket{\nu'},
\end{equation*}
where $\ket{\nu'} := D_{\reg{W_1^i}\reg{M_1^i}}\ket\nu$ which still has 2-norm at most $\nu$ as $D \preccurlyeq \id$.

By the theorem's assumption, the state $\ket{\aux}$ satisfies $\Tr(\wt{G_{i}} \proj{\aux}) \geq \tau\delta^{i}$, thus $\norm{D^{(\le i)}AC^{(\leq k)}\ket{\init}} = \norm{G_i\ket{\init}} = \norm{\wt{G_i}\ket{\aux}} \ge \sqrt{\tau\delta^i}$.
Therefore, the above state has $2$-norm at least
\begin{equation*}
    \gamma\sqrt{\tau\delta^i} - \nu = (1 - \mu)\sqrt{\tau\delta} - \mu\sqrt{\tau\delta} = (1 - 2\mu)\sqrt{\tau\delta}.
\end{equation*}  
So the prover is accepted with probability at least $(1 - 2\mu)^2\tau\delta$.
Finally the running time can be verified by plugging in the appropriate parameters and noting that $A$ is only used in \cref{step:invokeadv} and $\wt\Pi$ as defined in \cref{def:tildePi} in \cref{step:gslw}.
\end{proof}
